"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/knowledge-base/variants/02-help-center";
export interface ArtemisHelpCenterProps { className?: string;  }
export function ArtemisHelpCenter({className}:ArtemisHelpCenterProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { Dialog, DialogBackdrop, DialogPanel, DialogTitle } from "../../../../lib/headless";
import { AnimatePresence, MotionConfig, motion, useReducedMotion } from "motion/react";
import { Check, Clock3, ThumbsDown, ThumbsUp, X } from "lucide-react";
import { useId, useState } from "react";
import { ArtemisButton } from "../../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../../lib/ease";
import { SECTIONS, TOPICS, type Article } from "./data";
export function ArticleDialog({ article, onClose }: {
    article: Article | null;
    onClose: () => void;
}) {
    const reduce = useReducedMotion();
    return <AnimatePresence>{article ? <Dialog static open onClose={onClose} className="art:relative art:z-[100]">
    <MotionConfig transition={reduce ? { duration: 0 } : { duration: 0.15, ease: ARTEMIS_EASE_OUT }}>
      <DialogBackdrop as={motion.div} className="art:fixed art:inset-0 art:bg-foreground/10 art:backdrop-blur-sm" initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1, transition: reduce ? { duration: 0 } : { duration: 0.2, ease: ARTEMIS_EASE_OUT } }} exit={{ opacity: 0 }}/>
      <div className="art:fixed art:inset-4 art:z-[101] art:overflow-x-hidden art:overflow-y-auto">
        <div className="art:flex art:min-h-full art:items-center art:justify-center">
          <DialogPanel as={motion.div} className="art:max-h-[calc(100dvh-2rem)] art:w-full art:overflow-y-auto art:border art:border-border art:bg-background art:text-foreground art:will-change-transform art:max-w-4xl art:rounded-2xl art:p-5 art:@min-[640px]/artemis:p-8" initial={reduce ? false : { opacity: 0, y: 8, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1, transition: reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL }} exit={{ opacity: 0, y: 6, scale: 0.96 }}>
            <DialogTitle className="art:sr-only">{article.title}</DialogTitle>
            <div className="art:mb-3 art:flex art:justify-end"><ArtemisButton variant="ghost" size="icon" className="art:size-9" aria-label="Close article" onClick={onClose}><X size={18}/></ArtemisButton></div>
            <ArticleBody article={article}/>
          </DialogPanel>
        </div>
      </div>
    </MotionConfig>
  </Dialog> : null}</AnimatePresence>;
}
function ArticleBody({ article }: {
    article: Article;
}) {
    const sectionId = useId();
    const [vote, setVote] = useState<"yes" | "no" | null>(null);
    const sections = SECTIONS[Number(article.id)];
    return <div className="art:min-w-0">
    <header className="art:mb-8"><p className="art:mb-3 art:text-xs art:font-medium art:text-muted-foreground">{TOPICS[article.topic]}</p><h3 className="art:text-xl art:font-medium">{article.title}</h3><p className="art:mt-4 art:text-sm art:leading-relaxed art:text-muted-foreground">{article.description}</p><p className="art:mt-4 art:flex art:items-center art:gap-2 art:text-xs art:text-muted-foreground"><Clock3 size={14}/>{`${article.minutes} min read`}</p></header>
    <div className="art:grid art:gap-8 art:@min-[1280px]/artemis:grid-cols-[minmax(0,1fr)_10rem]">
      <div className="art:space-y-8">{sections.map((section, index) => <section key={section.title} id={`${sectionId}-section-${index}`} className="art:scroll-mt-6"><h4 className="art:text-xl art:font-medium">{section.title}</h4><p className="art:mt-3 art:text-sm art:leading-7 art:text-muted-foreground">{section.content}</p>{section.steps ? <ol className="art:mt-4 art:space-y-3">{section.steps.map((step, stepIndex) => <li key={step} className="art:flex art:gap-3 art:text-sm art:leading-6"><span className="art:flex art:size-6 art:shrink-0 art:items-center art:justify-center art:rounded-full art:border art:border-border art:text-xs art:tabular-nums">{stepIndex + 1}</span><span>{step}</span></li>)}</ol> : null}</section>)}</div>
      <nav aria-label="On this page" className="art:hidden art:self-start art:border-l art:border-border art:pl-4 art:@min-[1280px]/artemis:block"><p className="art:mb-3 art:text-xs art:font-medium">On this page</p>{sections.map((section, index) => <a key={section.title} href={`#${sectionId}-section-${index}`} className="art:block art:rounded-lg art:py-2 art:text-xs art:leading-relaxed art:text-muted-foreground art:outline-none art:hover:text-foreground art:focus-visible:ring-2 art:focus-visible:ring-ring">{section.title}</a>)}</nav>
    </div>
    <div className="art:mt-10 art:flex art:flex-wrap art:items-center art:justify-between art:gap-4 art:border-t art:border-border art:pt-5"><p aria-live="polite" className="art:flex art:items-center art:gap-2 art:text-xs art:text-muted-foreground">{vote ? <><Check size={14}/>Thanks — your feedback is noted for this preview.</> : "Was this article helpful?"}</p><div className="art:flex art:gap-2"><ArtemisButton variant="tertiary" className="art:h-9 art:text-xs" aria-pressed={vote === "yes"} onClick={() => setVote("yes")}><ThumbsUp size={14}/>Yes</ArtemisButton><ArtemisButton variant="tertiary" className="art:h-9 art:text-xs" aria-pressed={vote === "no"} onClick={() => setVote("no")}><ThumbsDown size={14}/>Not quite</ArtemisButton></div></div>
  </div>;
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
import type { Article } from "./data";
export function ArticleRow({ article, onRead }: {
    article: Article;
    onRead: (article: Article) => void;
}) {
    const reduce = useReducedMotion();
    return (<div className="art:flex art:w-full art:items-center art:gap-4 art:px-1 art:py-5 art:text-left">
                  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-file-text art:shrink-0 art:text-muted-foreground" aria-hidden="true">
                    <path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z"/>
                    <path d="M14 2v5a1 1 0 0 0 1 1h5"/>
                    <path d="M10 9H8"/>
                    <path d="M16 13H8"/>
                    <path d="M16 17H8"/>
                  </svg>
                  <span className="art:min-w-0 art:flex-1">
                    <span className="art:block art:text-sm art:font-medium">
                      {article.title}
                    </span>
                    <span className="art:mt-1 art:block art:text-xs art:leading-relaxed art:text-muted-foreground">
                      {article.description}
                    </span>
                  </span>
                  <span className="art:hidden art:text-xs art:text-muted-foreground art:@min-[640px]/artemis:block">
                    {article.minutes}
                    {" min"}
                  </span>
                  <motion.button whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:size-9 art:shrink-0 art:after:absolute art:after:-inset-1 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" aria-label={`Read ${article.title}`} onClick={() => onRead(article)} tabIndex={0}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right" aria-hidden="true">
                      <path d="M5 12h14"/>
                      <path d="m12 5 7 7-7 7"/>
                    </svg>
                  </motion.button>
                </div>);
}

// @zeus-internal
